// Region3D: canonical layout, generated by tools/header_adopt_lane.py from
// reverse/class_contracts/Region3D.json (variant data), then given the Zero Hour members
// (GeneralsMD BaseType.h Region3D) every private view defined inline. Edit the contract for layout.
// sizeof 24 (zh); class-key struct (bytes).
#ifndef CANONICAL_REGION3D_H
#define CANONICAL_REGION3D_H

struct Region3D {
    Coord3D lo;
    Coord3D hi;
    float width() const { return hi.x - lo.x; }
    float height() const { return hi.y - lo.y; }
    float depth() const { return hi.z - lo.z; }
    bool isInRegionNoZ(const Coord3D *query) const
    {
        return (lo.x < query->x) && (query->x < hi.x)
            && (lo.y < query->y) && (query->y < hi.y);
    }
    bool isInRegionWithZ(const Coord3D *query) const
    {
        return (lo.x < query->x) && (query->x < hi.x)
            && (lo.y < query->y) && (query->y < hi.y)
            && (lo.z < query->z) && (query->z < hi.z);
    }
};

#endif // CANONICAL_REGION3D_H
